CREATE TABLE IF NOT EXISTS affiliates (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, passwordHash TEXT NOT NULL, name TEXT NOT NULL, company TEXT, phone TEXT, commissionRate NUMERIC NOT NULL DEFAULT 10, affiliateCode TEXT NOT NULL UNIQUE, agentNumber TEXT, isActive INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'pending', createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS affiliateReferrals (id INTEGER PRIMARY KEY AUTOINCREMENT, affiliateId INTEGER NOT NULL, referralCode TEXT NOT NULL UNIQUE, visitorEmail TEXT, visitorName TEXT, visitorPhone TEXT, status TEXT NOT NULL DEFAULT 'pending', commissionAmount NUMERIC DEFAULT 0, notes TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS policies (id INTEGER PRIMARY KEY AUTOINCREMENT, affiliateId INTEGER NOT NULL, policyNumber TEXT NOT NULL UNIQUE, clientName TEXT NOT NULL, clientEmail TEXT, clientPhone TEXT, policyType TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', points INTEGER DEFAULT 0, submittedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, approvedAt TEXT, createdAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_affiliate_referrals_affiliate ON affiliateReferrals(affiliateId, createdAt);
PRAGMA optimize;
